    # Initialize the maximum value to negative infinity
    max_value = float('-inf')

    # Recursively search through the nested structure
    def traverse(data):
        nonlocal max_value
        for item in data:
            if isinstance(item, (list, tuple)):
                traverse(item)
            elif isinstance(item, (int, float)):
                max_value = max(max_value, item)

    traverse(nested_structure)

    # Return the maximum value found
    return max_value
