    def helper(value):
        if isinstance(value, list):
            # Recursively applying helper on each element of the list
            return max(helper(sub_value) for sub_value in value)
        elif isinstance(value, int) or isinstance(value, float):
            # Returning the value if it's a numeric type
            return value
        else:
            # Returning None for non-numeric types
            return None

    # Starting the search from the root of the nested structure
    return helper(nested_structure)
