def find_maximum_nested_value(nested_structure):
    # Base case: if the structure is a number, return it
    if isinstance(nested_structure, (int, float)):
        return nested_structure

    # Recursive case: if the structure is a list, iterate through its elements
    elif isinstance(nested_structure, list):
        max_value = None
        for element in nested_structure:
            sub_max_value = find_maximum_nested_value(element)
            if max_value is None or sub_max_value > max_value:
                max_value = sub_max_value
        return max_value

    # Handle other types of structures (like dictionaries, etc.) if necessary
    else:
        raise ValueError("Unsupported type in nested structure")
```
