function mergeSortedArrays(arr1: number[], arr2: number[]): number[] {
  let i = 0, j = 0;
  const mergedArray = [];
  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] <= arr2[j]) {
      mergedArray.push(arr1[i]);
      i++;
    } else {
      mergedArray.push(arr2[j]);
      j++;
    }
  }
  return mergedArray.concat(arr1.slice(i)).concat(arr2.slice(j));
