```typescript
function getMaxNestedValue(nestedStructure: any): number | undefined {
  if (typeof nestedStructure === 'number') {
    return nestedStructure;
  } else if (nestedStructure instanceof Array) {
    return nestedStructure.reduce((max, val) => Math.max(max, getMaxNestedValue(val)), -Infinity);
  } else if (nestedStructure !== null && typeof nestedStructure === 'object') {
    return Object.values(nestedStructure).reduce((max, val) => Math.max(max, getMaxNestedValue(val)), -Infinity);
  } else {
    return undefined;
  }
}
