function findMaxInNestedStructure(nestedStructure: any): number | null {
  let max = -Infinity;
  for (const key in nestedStructure) {
    if (nestedStructure.hasOwnProperty(key)) {
      const value = nestedStructure[key];
      if (typeof value === 'number') {
        max = Math.max(max, value);
      } else if (typeof value === 'object' && value !== null) {
        const childMax = findMaxInNestedStructure(value);
        if (childMax !== null && childMax > max) {
          max = childMax;
        }
      }
    }
  }
  return max !== -Infinity ? max : null;
}
```

