  // Helper function to recursively find the maximum value in a nested structure.
  function findMax(obj: any): number | null {
    if (Array.isArray(obj)) {
      return Math.max(...obj.map(findMax), -Infinity);
    } else if (typeof obj === 'object' && obj !== null) {
      return Object.values(obj).reduce((max, value) => Math.max(max, findMax(value)), -Infinity);
    } else if (typeof obj === 'number') {
      return obj;
    } else {
      return -Infinity;
    }
  }

  return findMax(nested_structure);
}
